-- ============================================================
-- 時系列点検記録データ（統合劣化スコアモデル）
-- 合計: 254,502 件 / 設備数: 300 件
-- モデル: バスタブ曲線 + 季節負荷 + 突発スパイク + 不完全修理
-- ============================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DELETE FROM inspection_records;
































































































































































































































































-- next_inspection_date を実際の最終点検日から再計算する
UPDATE equipment e
JOIN (
    SELECT equipment_id, MAX(inspected_at) AS last_date
    FROM inspection_records
    GROUP BY equipment_id
) latest ON e.id = latest.equipment_id
SET e.next_inspection_date = DATE_ADD(
    latest.last_date,
    INTERVAL e.inspection_interval_months MONTH
)
WHERE e.deleted_at IS NULL;

SET FOREIGN_KEY_CHECKS = 1;
-- 完了
